#include <stack>
#include <vector>

void process_stack(std::stack<int> s) {
    if (!s.empty()) {
        // 1. Access the value (top())
        int value = s.top(); 

        // 2. Remove the value (pop() returns void)
        s.pop(); 

        // The value is safe even if copy fails, because pop()
        // only modifies state after successful access.
    }
}
